"use strict";
import LogoProvider from "components/Logo/LogoProvider";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { useModalState } from "hooks/useModalState";
import { useVoterContract } from "hooks/useVoterContract";
import { useLockVotingStatus } from "hooks/useVotingStatus";
import { useEffect, useMemo } from "react";
import { AlertCircle, CheckCircle, Lock, X } from "react-feather";
import { useNavigate } from "react-router-dom";
import { useAppDispatch, useAppSelector } from "state/hooks";
import { clearPendingVotes, selectPendingVotes, selectSelectedLock } from "state/voting/slice";
import styled from "styled-components";
import { Flex, SpinningLoader, StarBorderButton, Text, styled as UiStyled, useMedia, useSporeColors } from "ui/src";
import { colors as ThemeColors } from "ui/src/theme";
import { ModalName } from "uniswap/src/features/telemetry/constants";
import { formatEther } from "viem";
export default function LockIncreaseExtendClearVote({ isVoteAble }) {
  const selectedLock = useAppSelector(selectSelectedLock);
  const pendingVotes = useAppSelector(selectPendingVotes);
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const media = useMedia();
  const { vote, transactionState } = useVoterContract();
  const { toggleModal: closeVotingModal } = useModalState(ModalName.Voting);
  const { hasVoted, isLoading: votingStatusLoading } = useLockVotingStatus(selectedLock?.id);
  const totalPercentage = useMemo(() => {
    return pendingVotes.reduce((sum, vote2) => sum + (vote2.percentage || 0), 0);
  }, [pendingVotes]);
  useEffect(() => {
    if (transactionState.isSuccess) {
      const timer = setTimeout(() => {
        dispatch(clearPendingVotes());
        closeVotingModal();
      }, 2e3);
      return () => clearTimeout(timer);
    }
  }, [transactionState.isSuccess, dispatch, closeVotingModal]);
  const handleVote = async () => {
    if (!selectedLock || pendingVotes.length === 0) {
      return;
    }
    if (hasVoted) {
      return;
    }
    if (totalPercentage !== 100) {
      return;
    }
    try {
      const votingPower = BigInt(selectedLock.votingPower);
      const voteAllocations = pendingVotes.map((pendingVote) => {
        const percentage = pendingVote.percentage || 0;
        const weightBigInt = votingPower * BigInt(Math.round(percentage * 100)) / BigInt(1e4);
        return {
          poolAddress: pendingVote.poolAddress,
          weight: Number(weightBigInt)
        };
      });
      await vote(selectedLock.id, voteAllocations);
    } catch (error) {
      console.error("Vote submission failed:", error);
    }
  };
  const TextWrap = UiStyled(Text, {
    variant: "buttonLabel3",
    color: "$neutral3",
    py: "$padding4",
    px: "$padding8",
    transition: "color 0.2s ease",
    hoverStyle: { color: "$neutral1" }
  });
  const buttonsArray = [
    {
      label: "Increase",
      action: () => {
        navigate("/lock");
      }
    },
    {
      label: "Extend",
      action: () => {
        navigate("/lock");
      }
    },
    {
      label: "Clear the votes",
      action: () => {
      }
    }
  ];
  const colors = useSporeColors();
  const Button = styled.button`
    all: unset;
    cursor: pointer;
  `;
  const VoteButton = styled(Button)`
    padding: 8px 16px;
    border-radius: 12px;
    background-color: ${(props) => props.disabled ? props.colors?.surface3?.val || "#E5E7EB" : props.colors?.neutral1?.val || "#1F2937"};
    color: ${(props) => props.disabled ? props.colors?.neutral3?.val || "#9CA3AF" : props.colors?.surface1?.val || "#FFFFFF"};
    text-align: center;
    transition: all 0.2s ease-in-out;
    cursor: ${(props) => props.disabled ? "not-allowed" : "pointer"};
    opacity: ${(props) => props.disabled ? 0.6 : 1};
    &:hover {
      background-color: ${(props) => props.disabled ? props.colors?.surface3?.val || "#E5E7EB" : props.colors?.neutral1Hovered?.val || props.colors?.neutral1?.val || "#374151"};
    }
  `;
  if (!selectedLock) {
    return null;
  }
  const formatAmount = (amount) => {
    const formatted = formatEther(BigInt(amount));
    const num = parseFloat(formatted);
    if (num < 1e3) return num.toFixed(2);
    if (num < 1e6) return (num / 1e3).toFixed(2) + "K";
    return (num / 1e6).toFixed(2) + "M";
  };
  const calculateLockDuration = () => {
    if (selectedLock.permanent) return "permanently";
    const now = Date.now() / 1e3;
    const lockEndSeconds = parseInt(selectedLock.lockEnd);
    const daysRemaining = Math.max(0, Math.floor((lockEndSeconds - now) / (24 * 60 * 60)));
    if (daysRemaining < 30) return `${daysRemaining} days`;
    if (daysRemaining < 365) return `${Math.floor(daysRemaining / 30)} months`;
    return `${Math.floor(daysRemaining / 365)} years`;
  };
  const formatLockEndDate = () => {
    if (selectedLock.permanent) return "locked permanently";
    return new Date(parseInt(selectedLock.lockEnd) * 1e3).toLocaleString();
  };
  return <Flex
    row
    gap={"$spacing24"}
    justifyContent="space-between"
    borderWidth={1}
    borderColor={"$surface3"}
    borderRadius={"$rounded12"}
    py={"$padding16"}
    px={"$padding12"}
    backgroundColor={"$surface1"}
    transition="background-color 0.2s ease-in-out"
    hoverStyle={{ backgroundColor: "$surface1Hovered" }}
    $platform-web={{
      position: "sticky",
      top: 0,
      left: 0,
      right: 0,
      zIndex: 20
    }}
    $lg={{
      flexDirection: "column",
      alignItems: "flex-start",
      position: "static"
    }}
  >
      <Flex row gap={"$gap24"} alignItems="flex-start">
        <Flex className="left" row gap={"$gap12"} alignItems="center">
          <Flex
    borderRadius={"$rounded8"}
    backgroundColor={"$slate"}
    borderWidth={1}
    borderColor={"$surface2Hovered"}
    centered
    height={40}
    width={40}
  >
            <LogoProvider size={24} />
          </Flex>

          <Flex row gap={"$gap12"} alignItems="flex-end">
            <Flex flexDirection="column" justifyContent="center" gap={"$gap8"}>
              <Flex row gap={"$gap12"} alignItems="center">
                <Text variant="body3">Lock #{selectedLock.id}</Text>
                <Lock size={14} color={colors.neutral3?.val || "#666666"} />
                {selectedLock.permanent && <Text variant="body4" color="$accent1">
                    ♾️
                  </Text>}
              </Flex>

              <MouseoverTooltip text={formatLockEndDate()} size={TooltipSize.Max} placement="top">
                <Text variant="body4" color="$neutral3" cursor="pointer">
                  {formatAmount(selectedLock.amount)} ABX locked{" "}
                  {selectedLock.permanent ? "permanently" : `for ${calculateLockDuration()}`}
                </Text>
              </MouseoverTooltip>
            </Flex>

            <Flex row gap={"$gap4"} mb={-2} $lg={{ display: "none" }}>
              {buttonsArray.map((button, index) => <Button key={index} onClick={button.action}>
                  <TextWrap>{button.label}</TextWrap>
                </Button>)}
            </Flex>
          </Flex>
        </Flex>
      </Flex>

      {isVoteAble ? <Flex flexDirection="column" gap="$spacing8" alignItems="flex-end" $xl={{ alignItems: "flex-start" }}>
          {
    /* Voting Status Warning */
  }
          {hasVoted && <Flex
    row
    gap="$spacing8"
    alignItems="center"
    backgroundColor="$surface2"
    p="$spacing8"
    borderRadius="$rounded8"
  >
              <X size={14} color={colors.statusCritical?.val || "#FF4747"} />
              <Text variant="body4" color="$statusCritical">
                This lock has already voted this epoch
              </Text>
            </Flex>}

          {
    /* Total Percentage Display */
  }
          <Flex row gap="$spacing8" alignItems="center">
            <Text variant="body4" color="$neutral3">
              Total Allocation:
            </Text>
            <Text
    variant="body3"
    color={totalPercentage === 100 ? "$greenVibrant" : totalPercentage > 100 ? "$statusCritical" : "$neutral2"}
  >
              {totalPercentage.toFixed(1)}%
            </Text>
          </Flex>

          {
    /* Vote Button */
  }
          <StarBorderButton
    as="button"
    className="button-clear"
    color="white"
    speed="3s"
    py={12}
    px={24}
    onClick={handleVote}
    disabled={hasVoted || totalPercentage !== 100 || transactionState.isLoading || transactionState.isConfirming}
  >
            <Flex row centered gap="$spacing8">
              {transactionState.isSuccess && <CheckCircle size={16} color={ThemeColors.greenVibrant || colors.accent1?.val || "#00D395"} />}
              {transactionState.error && <AlertCircle size={16} color={colors.statusCritical?.val || colors.neutral3?.val || "#FF4747"} />}
              <Flex row alignItems="center" gap={"$gap8"}>
                {(transactionState.isLoading || transactionState.isConfirming) && <SpinningLoader size={16} />}
                <Text variant="buttonLabel3">
                  {hasVoted ? "Lock Already Voted" : transactionState.isSuccess ? "Vote Submitted!" : transactionState.isLoading ? "Preparing" : transactionState.isConfirming ? "Confirming" : totalPercentage !== 100 ? "Allocate 100% to Vote" : "Vote"}
                  {
    /* : `Vote (${pendingVotes.length} pool${pendingVotes.length !== 1 ? 's' : ''})`} */
  }
                </Text>
              </Flex>
            </Flex>
          </StarBorderButton>

          {
    /* Error Display */
  }
          {transactionState.error && <Text variant="body4" color="$statusCritical" maxWidth={200} textAlign="right">
              {transactionState.error}
            </Text>}
        </Flex> : <Flex
    flexDirection="column"
    alignItems="flex-end"
    gap={"$gap8"}
    width={"unset"}
    $md={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", width: "100%" }}
  >
          <Text variant="body4" color={"$neutral3"}>
            Total Voting Power
          </Text>
          <Text variant={media.md ? "body4" : "body3"} color={"$greenVibrant"}>
            99.95% available
          </Text>
        </Flex>}
    </Flex>;
}
