"use strict";
import { Token } from "@uniswap/sdk-core";
import { DoubleCurrencyLogo } from "components/Logo/DoubleLogo";
import PoolAndGaugeAddress from "components/PoolAndGaugeAddress";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { useEffect, useMemo, useRef, useState } from "react";
import { Delete } from "react-feather";
import { useAppDispatch } from "state/hooks";
import { updatePendingVoteWeight } from "state/voting/slice";
import styled from "styled-components";
import { Flex, Text, styled as UiStyled, useMedia, useSporeColors } from "ui/src";
import { GoldenVerified, InfoCircleFilled } from "ui/src/components/icons";
import { ABSTRACT_TESTNET_CHAIN_ID } from "uniswap/src/constants/contracts";
const StyledInput = styled.input`
  text-align: right;
  padding: 8px 0;
  background-color: transparent;
  border: none;
  outline: none;
  max-width: 140px;
  width: 100%;
  font-size: 18px;
  @media (max-width: 768px) {
    font-size: 14px;
    padding: 3px 0;
  }
`;
export default function VoteAllocationRow({ vote }) {
  const dispatch = useAppDispatch();
  const inputRef = useRef(null);
  const [inputValue, setInputValue] = useState("0");
  const colors = useSporeColors();
  const media = useMedia();
  useEffect(() => {
    if (vote.percentage > 0) {
      setInputValue(vote.percentage.toFixed(1));
    }
  }, [vote.percentage]);
  const handleChange = (text) => {
    const numericValue = text.replace(/[^0-9.]/g, "");
    const num = parseFloat(numericValue) || 0;
    const clampedNum = Math.min(100, Math.max(0, num));
    setInputValue(numericValue);
    dispatch(
      updatePendingVoteWeight({
        poolAddress: vote.poolAddress,
        weight: clampedNum
      })
    );
  };
  const handlePercentageClick = (percentage) => {
    setInputValue(percentage.toString());
    dispatch(
      updatePendingVoteWeight({
        poolAddress: vote.poolAddress,
        weight: percentage
      })
    );
  };
  const Button = styled.button`
    all: unset;
    padding: 2px 8px;
    background-color: ${colors.surface2Hovered.val};
    border-radius: 999px;
    cursor: pointer;
    transition: all 0.2s ease;
    &:hover {
      opacity: 0.7;
    }
  `;
  const DeleteButton = styled(Button)``;
  const SubTitle = UiStyled(Text, {
    variant: "body3",
    color: "$neutral3"
  });
  const ItemWrap = UiStyled(Flex, {
    flexDirection: "column",
    gap: "$spacing24",
    justifyContent: "space-between",
    backgroundColor: "$slate",
    borderRadius: "$rounded12",
    p: "$spacing12",
    alignItems: "flex-end",
    $xl: {
      flexDirection: "row"
    }
  });
  const CustomText = UiStyled(Text, {
    variant: media.md ? "body4" : "body2"
  });
  const buttonsArray = [10, 25, 50, 75, 100];
  const currencies = useMemo(() => {
    if (!vote.pool?.token0 || !vote.pool?.token1) return [void 0, void 0];
    try {
      const token0 = new Token(
        ABSTRACT_TESTNET_CHAIN_ID,
        vote.pool.token0.id,
        parseInt(vote.pool.token0.decimals),
        vote.pool.token0.symbol,
        vote.pool.token0.name
      );
      const token1 = new Token(
        ABSTRACT_TESTNET_CHAIN_ID,
        vote.pool.token1.id,
        parseInt(vote.pool.token1.decimals),
        vote.pool.token1.symbol,
        vote.pool.token1.name
      );
      return [token0, token1];
    } catch (error) {
      console.warn("Failed to create tokens for pool logos:", error);
      return [void 0, void 0];
    }
  }, [vote.pool?.token0, vote.pool?.token1]);
  const poolName = vote.pool?.token0?.symbol && vote.pool?.token1?.symbol ? `${vote.pool.token0.symbol}/${vote.pool.token1.symbol}` : `${vote.poolAddress.slice(0, 6)}...${vote.poolAddress.slice(-4)}`;
  return <Flex
    $platform-web={{ display: "grid", gridTemplateColumns: "12fr 8fr 8fr 10fr" }}
    gap={"$spacing12"}
    $xl={{ gridTemplateColumns: "1fr", gap: "$spacing8" }}
    backgroundColor={"$surface1Hovered"}
    p={"$padding12"}
    transition="background-color 0.2s ease"
    hoverStyle={{ backgroundColor: "$surface2" }}
    borderRadius={"$rounded12"}
  >
      {
    /* Pool Info */
  }
      <Flex $xl={{ mb: "$gap20" }} group className="info" row gap={"$gap12"} alignItems="center">
        <DoubleCurrencyLogo currencies={currencies} size={40} />

        <Flex flexDirection="column" justifyContent="center" gap={"$gap4"}>
          <Flex row gap={"$gap8"} alignItems="center">
            <Text variant="subheading1">{poolName}</Text>
            <GoldenVerified size={"$icon.18"} />
            {vote.pool && <MouseoverTooltip
    text={vote.pool.poolType ? "Pool Trading Fee" : "Pool Trading Fee"}
    size={TooltipSize.Max}
    placement="top"
  >
                <Text
    backgroundColor={"$surface3"}
    py={"$padding4"}
    px={"$padding8"}
    borderRadius={"$rounded8"}
    variant="body3"
    cursor="pointer"
    hoverStyle={{ backgroundColor: "$surface3Hovered" }}
  >
                  {
    /* {vote.pool.poolType || '0.3%'} */
  }
                  {"0.3%"}
                </Text>
              </MouseoverTooltip>}
            <MouseoverTooltip
    text={<PoolAndGaugeAddress poolAddress={vote.pool?.pool} gaugeAddress={vote.pool?.id} />}
    size={TooltipSize.Max}
    placement="top"
  >
              <Flex
    cursor="pointer"
    transition="opacity 0.3s ease"
    opacity={0}
    $md={{ opacity: 1 }}
    $group-hover={{ opacity: 1 }}
  >
                <InfoCircleFilled size={"$icon.18"} color={"$neutral2"} />
              </Flex>
            </MouseoverTooltip>
          </Flex>
          <Text variant="body3" fontWeight={"$medium"} color={"$neutral2"}>
            {vote.pool?.reserveUSD ? `$${(parseFloat(vote.pool.reserveUSD) / 1e6).toFixed(1)}M TVL` : "TVL: N/A"}
          </Text>
        </Flex>
      </Flex>
      <ItemWrap>
        {
    /* Total Weight Info */
  }
        <Flex
    flexDirection="column"
    $xl={{ flexDirection: "row", gap: "$gap12", justifyContent: "space-between" }}
    gap={"$gap12"}
  >
          <SubTitle>vAPR</SubTitle>
          <CustomText>{vote.pool?.votes ? `${(parseFloat(vote.pool.votes) / 1e6).toFixed(1)}M` : "N/A"}</CustomText>
        </Flex>
      </ItemWrap>
      <ItemWrap>
        {
    /* Est. Rewards */
  }
        <Flex
    flexDirection="column"
    alignItems="flex-end"
    $xl={{ flexDirection: "row", gap: "$gap12", justifyContent: "space-between", alignItems: "center" }}
    gap={"$spacing12"}
  >
          <SubTitle>Est. Rewards</SubTitle>
          <CustomText>~$0.024</CustomText>
        </Flex>
      </ItemWrap>
      <ItemWrap $xl={{ justifyContent: "flex-end" }}>
        {
    /* Voting Power Percentage */
  }
        <Flex flexDirection="column" gap={"$spacing12"} alignItems="flex-end" width={"100%"}>
          <SubTitle>Voting Power %</SubTitle>
          <Flex
    row
    px="$spacing8"
    py={"$spacing4"}
    borderWidth={1}
    borderColor={"$surface3"}
    justifyContent="space-between"
    alignItems="center"
    gap={"$gap4"}
    borderRadius={"$rounded12"}
    overflow="hidden"
    flex={1}
    onPress={() => inputRef.current?.focus()}
    $platform-web={{
      focusWithinStyle: { borderColor: "$neutral2" }
    }}
    transition="border-color 0.3s ease"
  >
            <Text>%</Text>
            <StyledInput
    ref={inputRef}
    onChange={(e) => handleChange(e.target.value)}
    type="text"
    value={inputValue}
    style={{ color: colors.neutral1.val }}
    placeholder="0"
  />
          </Flex>

          <Flex row gap={"$gap4"} alignItems="center" justifyContent="flex-end" flexWrap="wrap">
            <DeleteButton onClick={() => handlePercentageClick(0)}>
              <Delete size={12} color={colors.neutral1.val} />
            </DeleteButton>
            {buttonsArray.map((button, btnIndex) => <Button key={btnIndex} onClick={() => handlePercentageClick(button)}>
                <Text variant="body4" textWrap="nowrap">
                  {button}%
                </Text>
              </Button>)}
          </Flex>
        </Flex>
      </ItemWrap>
    </Flex>;
}
